@extends('layouts.app') @section('title','Tasks') @section('content')<div class="row"><div><h1>My Tasks</h1><p>Manage your personal tasks and deadlines.</p></div><a class="btn primary" href="{{ route('tasks.create') }}">+ Add Task</a></div><div class="card">@if($tasks->isEmpty())<p>No tasks yet.</p>@else<table><tr><th>Task</th><th>Description</th><th>Status</th><th>Due date</th><th>Actions</th></tr>@foreach($tasks as $task)<tr><td>{{ $task->task_name }}</td><td>{{ $task->description ?: '—' }}</td><td><span class="badge {{ $task->status }}">{{ $task->status }}</span></td><td>{{ $task->due_date->format('M d, Y') }}</td><td><div class="actions"><a class="btn secondary" href="{{ route('tasks.edit',$task) }}">Edit</a><form method="POST" action="{{ route('tasks.status',$task) }}">@csrf @method('PATCH')<input type="hidden" name="status" value="{{ $task->status === 'Pending' ? 'Completed' : 'Pending' }}"><button class="btn success">{{ $task->status === 'Pending' ? 'Complete' : 'Pending' }}</button></form><form method="POST" action="{{ route('tasks.destroy',$task) }}" onsubmit="return confirm('Delete this task?')">@csrf @method('DELETE')<button class="btn danger">Delete</button></form></div></td></tr>@endforeach</table>@endif</div>@endsection
